SQL_STMT_U.val:
SELECT x.is_header, x.customer_id, x.billing_customer_id, x.tax_category, x.tax_type, x.branch_type, x.name, x.previous_balance, x.payment_amount, x.standard_sales_amount, x.standard_return_amount, x.standard_discount_amount, x.standard_tax_amount, x.reduced_sales_amount, x.reduced_return_amount, x.reduced_discount_amount, x.reduced_tax_amount, x.current_balance FROM ( /* 見出し行 */ SELECT 1 AS is_header, ps.id AS customer_id, ps.payment_destination_id AS billing_customer_id, ps.tax_category, ps.consumption_tax_type AS tax_type, 0 AS branch_type, ps.name, 0 AS previous_balance, 0 AS payment_amount, 0 AS standard_sales_amount, 0 AS standard_return_amount, 0 AS standard_discount_amount, 0 AS standard_tax_amount, 0 AS reduced_sales_amount, 0 AS reduced_return_amount, 0 AS reduced_discount_amount, 0 AS reduced_tax_amount, 0 AS current_balance, ps.id AS sort_parent_id, 0 AS sort_type, ps.id AS sort_customer_id FROM ( SELECT DISTINCT COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) AS payment_destination_id FROM payables_file AS pf LEFT JOIN supplier AS s ON s.id = pf.supplier_id WHERE pf.year_month = ':1' AND ( (:2 = 0 AND :3 = 0) OR ( COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) BETWEEN :2 AND :3 ) ) AND ( COALESCE(pf.previous_balance, 0) <> 0 OR COALESCE(pf.payment_amount, 0) <> 0 OR COALESCE(pf.standard_purchase_amount, 0) <> 0 OR COALESCE(pf.standard_return_amount, 0) <> 0 OR COALESCE(pf.standard_discount_amount, 0) <> 0 OR COALESCE(pf.standard_taxamount, 0) <> 0 OR COALESCE(pf.reduced_purchase_amount, 0) <> 0 OR COALESCE(pf.reduced_return_amount, 0) <> 0 OR COALESCE(pf.reduced_discount_amount, 0) <> 0 OR COALESCE(pf.reduced_tax_amount, 0) <> 0 OR COALESCE(pf.current_balance, 0) <> 0 ) ) h INNER JOIN supplier AS ps ON ps.id = h.payment_destination_id
UNION ALL
/* 明細行 */ SELECT 0 AS is_header, pf.supplier_id AS customer_id, s.payment_destination_id AS billing_customer_id, s.tax_category, s.consumption_tax_type AS tax_type, 0 AS branch_type, s.name, pf.previous_balance, pf.payment_amount, pf.standard_purchase_amount AS standard_sales_amount, pf.standard_return_amount, pf.standard_discount_amount, pf.standard_taxamount AS standard_tax_amount, pf.reduced_purchase_amount AS reduced_sales_amount, pf.reduced_return_amount, pf.reduced_discount_amount, pf.reduced_tax_amount, pf.current_balance, COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) AS sort_parent_id, 1 AS sort_type, pf.supplier_id AS sort_customer_id FROM payables_file AS pf LEFT JOIN supplier AS s ON s.id = pf.supplier_id WHERE pf.year_month = ':1' AND ( (:2 = 0 AND :3 = 0) OR ( COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) BETWEEN :2 AND :3 ) ) AND ( COALESCE(pf.previous_balance, 0) <> 0 OR COALESCE(pf.payment_amount, 0) <> 0 OR COALESCE(pf.standard_purchase_amount, 0) <> 0 OR COALESCE(pf.standard_return_amount, 0) <> 0 OR COALESCE(pf.standard_discount_amount, 0) <> 0 OR COALESCE(pf.standard_taxamount, 0) <> 0 OR COALESCE(pf.reduced_purchase_amount, 0) <> 0 OR COALESCE(pf.reduced_return_amount, 0) <> 0 OR COALESCE(pf.reduced_discount_amount, 0) <> 0 OR COALESCE(pf.reduced_tax_amount, 0) <> 0 OR COALESCE(pf.current_balance, 0) <> 0 )
UNION ALL
/* 支払先計行 */ SELECT 2 AS is_header, COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) AS customer_id, COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) AS billing_customer_id, MAX(ps.tax_category) AS tax_category, MAX(ps.consumption_tax_type) AS tax_type, 0 AS branch_type, '【仕 入 先 計】' AS name, SUM(COALESCE(pf.previous_balance, 0)) AS previous_balance, SUM(COALESCE(pf.payment_amount, 0)) AS payment_amount, SUM(COALESCE(pf.standard_purchase_amount, 0)) AS standard_sales_amount, SUM(COALESCE(pf.standard_return_amount, 0)) AS standard_return_amount, SUM(COALESCE(pf.standard_discount_amount, 0)) AS standard_discount_amount, SUM(COALESCE(pf.standard_taxamount, 0)) AS standard_tax_amount, SUM(COALESCE(pf.reduced_purchase_amount, 0)) AS reduced_sales_amount, SUM(COALESCE(pf.reduced_return_amount, 0)) AS reduced_return_amount, SUM(COALESCE(pf.reduced_discount_amount, 0)) AS reduced_discount_amount, SUM(COALESCE(pf.reduced_tax_amount, 0)) AS reduced_tax_amount, SUM(COALESCE(pf.current_balance, 0)) AS current_balance, COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) AS sort_parent_id, 9 AS sort_type, 999999999 AS sort_customer_id FROM payables_file AS pf LEFT JOIN supplier AS s ON s.id = pf.supplier_id LEFT JOIN supplier AS ps ON ps.id = COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) WHERE pf.year_month = ':1' AND ( (:2 = 0 AND :3 = 0) OR ( COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) BETWEEN :2 AND :3 ) ) AND ( COALESCE(pf.previous_balance, 0) <> 0 OR COALESCE(pf.payment_amount, 0) <> 0 OR COALESCE(pf.standard_purchase_amount, 0) <> 0 OR COALESCE(pf.standard_return_amount, 0) <> 0 OR COALESCE(pf.standard_discount_amount, 0) <> 0 OR COALESCE(pf.standard_taxamount, 0) <> 0 OR COALESCE(pf.reduced_purchase_amount, 0) <> 0 OR COALESCE(pf.reduced_return_amount, 0) <> 0 OR COALESCE(pf.reduced_discount_amount, 0) <> 0 OR COALESCE(pf.reduced_tax_amount, 0) <> 0 OR COALESCE(pf.current_balance, 0) <> 0 ) GROUP BY COALESCE(NULLIF(s.payment_destination_id, 0), pf.supplier_id) ) x ORDER BY x.sort_parent_id, x.sort_type, x.sort_customer_id;
